 for(bool en:{false,true})for(int profileIndex=0;profileIndex<3;++profileIndex){w.en=en;w.mode=en?2:1;w.applyTheme();setUiLanguage(en);SqlDialog dialog(m,en,en,nullptr,&w);dialog.findChild<QComboBox*>("sqlProfile")->setCurrentIndex(profileIndex);dialog.show();qApp->processEvents();auto tree=dialog.findChild<QTreeWidget*>("physicalTree");tree->setCurrentItem(tree->topLevelItem(0)->child(0));qApp->processEvents();check("SQL settings fit available screen",dialog.width()<=dialog.screen()->availableGeometry().width()&&dialog.height()<=dialog.screen()->availableGeometry().height());auto generate=dialog.findChild<QPushButton*>("generateSql");check("Generate button visible within dialog",generate&&generate->isVisible()&&dialog.rect().contains(QRect(generate->mapTo(&dialog,QPoint()),generate->size())));dialog.grab().save(output+QString("/physical-%1-%2.png").arg(profileIndex).arg(en?"en":"it"));check("Native SQL generation",dialog.regenerate(false));qApp->processEvents();check("SQL editor usable",dialog.editor->viewport()->width()>320&&dialog.editor->viewport()->height()>130);dialog.grab().save(output+QString("/sql-%1-%2.png").arg(profileIndex).arg(en?"en":"it"));dialog.accept();}
 QFile file(output+"/sql-display-results.json");if(!file.open(QIODevice::WriteOnly))return 2;file.write(QJsonDocument(QJsonObject{{"failures",failures},{"checks",checks},{"devicePixelRatio",w.devicePixelRatioF()}}).toJson());return failures?1:0;
